-- ============================================================
-- اختبارات تفاعلية — كتاب الكيمياء للصف السادس العلمي (8 فصول)
-- مُولَّدة من محتوى ملف PDF الموجود في مكتبة المواد.
-- كل سؤال يحمل في تفسيره رقم الصفحة واقتباساً حرفياً من الكتاب.
-- الاختبارات تُنشأ كمسودات (is_active = false) لتراجعها ثم تنشرها من لوحة المدرّس.
-- السكربت آمن لإعادة التشغيل: لا يكرر اختباراً موجوداً بالعنوان نفسه.
-- يُشغَّل من Supabase SQL Editor.
-- ============================================================
DO $$
DECLARE
  v_course UUID; v_chapter UUID; v_quiz UUID;
BEGIN
  SELECT id INTO v_course FROM public.courses
   WHERE grade_id = 3 AND title LIKE 'الكيمياء%' ORDER BY created_at LIMIT 1;
  IF v_course IS NULL THEN
    RAISE EXCEPTION 'لم أجد مادة الكيمياء للصف السادس (grade_id = 3). أنشئ المادة أولاً ثم أعد التشغيل.';
  END IF;


  -- ===== الفصل الأول: الثرموداينمك =====
  SELECT id INTO v_chapter FROM public.chapters WHERE course_id = v_course AND (title = $q$الفصل الأول: الثرموداينمك$q$ OR sort_order = 1) ORDER BY created_at LIMIT 1;
  IF v_chapter IS NULL THEN
    INSERT INTO public.chapters (course_id, title, sort_order) VALUES (v_course, $q$الفصل الأول: الثرموداينمك$q$, 1) RETURNING id INTO v_chapter;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.quizzes WHERE chapter_id = v_chapter AND title = $q$اختبار تفاعلي — الفصل الأول: الثرموداينمك$q$) THEN
    INSERT INTO public.quizzes (chapter_id, title, description, pass_score, is_active)
    VALUES (v_chapter, $q$اختبار تفاعلي — الفصل الأول: الثرموداينمك$q$, $q$أسئلة مستخرجة من كتاب الكيمياء (PDF) مع تفسير علمي ومرجع الصفحة$q$, 50, false) RETURNING id INTO v_quiz;
    INSERT INTO public.questions (quiz_id, question_text, options, correct_answer, explanation, sort_order) VALUES
      (v_quiz, $q$ينص القانون الأول في علم الثرموداينمك على أن:$q$, $q$[{"key": "A", "text": "الطاقة تفنى عند تحولها من شكل إلى آخر"}, {"key": "B", "text": "الحرارة تنتقل تلقائياً من الجسم البارد إلى الجسم الحار"}, {"key": "C", "text": "كل تفاعل باعث للحرارة يحدث تلقائياً"}, {"key": "D", "text": "الطاقة لا تفنى ولا تستحدث من العدم ولكن يمكن تحويلها من شكل إلى آخر"}]$q$::jsonb, 'D', $q$القانون الأول هو قانون حفظ الطاقة: الطاقة تتحول ولا تفنى ولا تُستحدث.

📖 المصدر: صفحة 10 — «الطاقة لا تفنى ولا تستحدث من العدم»$q$, 1),
      (v_quiz, $q$صحيحة أم خاطئة؟ — يهتم علم الثرموداينمك بالزمن الذي يستغرقه حدوث التفاعل.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$الثرموداينمك يبيّن هل التفاعل قابل للحدوث أم لا، أما سرعة التفاعل فمن اهتمام علم الحركيات.

📖 المصدر: صفحة 10 — «سرعة حدوث التفاعل من اهتمام علم الحركيات»$q$, 2),
      (v_quiz, $q$النظام الذي تسمح حدوده بتبادل الطاقة فقط ولا تسمح بتغيير كمية مادته هو النظام:$q$, $q$[{"key": "A", "text": "المعزول"}, {"key": "B", "text": "المفتوح"}, {"key": "C", "text": "المغلق"}, {"key": "D", "text": "المتجانس"}]$q$::jsonb, 'C', $q$النظام المغلق يتبادل الطاقة مع المحيط دون المادة، مثل إناء معدني فيه ماء مغلق بإحكام.

📖 المصدر: صفحة 12 — «تسمح بتبادل الطاقة فقط ولا تسمح بتغيير كمية مادة النظام»$q$, 3),
      (v_quiz, $q$يُعد الثرموس مثالاً على النظام:$q$, $q$[{"key": "A", "text": "المعزول"}, {"key": "B", "text": "المفتوح"}, {"key": "C", "text": "المتغير"}, {"key": "D", "text": "المغلق"}]$q$::jsonb, 'A', $q$النظام المعزول لا يتبادل المادة ولا الطاقة مع المحيط، والثرموس يحفظ حرارة النظام ومادته من التسرب.

📖 المصدر: صفحة 12 — «مثال ذلك، الثرموس»$q$, 4),
      (v_quiz, $q$الحرارة النوعية هي كمية الحرارة اللازمة لرفع درجة حرارة:$q$, $q$[{"key": "A", "text": "لتر واحد من المادة درجة كلفن واحدة"}, {"key": "B", "text": "غرام واحد من المادة درجة سيليزية واحدة"}, {"key": "C", "text": "مول واحد من المادة درجة سيليزية واحدة"}, {"key": "D", "text": "كتلة m من المادة درجة سيليزية واحدة"}]$q$::jsonb, 'B', $q$الحرارة النوعية تخص كتلة غرام واحد (وحدتها J/g·°C)، أما السعة الحرارية فتخص كتلة معينة m.

📖 المصدر: صفحة 13 — «كمية الحرارة اللازمة لرفع درجة حرارة كتلة غرام واحد»$q$, 5),
      (v_quiz, $q$ما مقدار الحرارة اللازمة لتسخين قطعة حديد كتلتها 870 g من 5°C إلى 95°C، علماً أن الحرارة النوعية للحديد 0.45 J/g·°C؟$q$, $q$[{"key": "A", "text": "391.5 J"}, {"key": "B", "text": "39150 J"}, {"key": "C", "text": "3523.5 J"}, {"key": "D", "text": "35235 J"}]$q$::jsonb, 'D', $q$q = الحرارة النوعية × الكتلة × التغير في درجة الحرارة = 0.45 × 870 × 90 = 35235 J (أي 35.2 kJ).

📖 المصدر: صفحة 14 — «× 870 )g( × 90 ) ̊ C( = 35235 J»$q$, 6),
      (v_quiz, $q$أي الكميات الآتية تُعد دالة حالة؟$q$, $q$[{"key": "A", "text": "المسار الذي يسلكه النظام"}, {"key": "B", "text": "الانثالبي"}, {"key": "C", "text": "الشغل"}, {"key": "D", "text": "الحرارة"}]$q$::jsonb, 'B', $q$دالة الحالة تعتمد على الحالة الابتدائية والنهائية فقط، والانثالبي مثال عليها، أما الحرارة والشغل فتعتمدان على المسار.

📖 المصدر: صفحة 15 — «ومن امثلة دالة الحالة، الانثالبي»$q$, 7),
      (v_quiz, $q$صحيحة أم خاطئة؟ — الانثالبي خاصية مركزة لا تعتمد على كمية المادة.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$الانثالبي دالة حالة وهي خاصية شاملة لأنها تعتمد على كمية المادة؛ فانثالبي تفاعل مولين ضعف انثالبي تفاعل مول واحد.

📖 المصدر: صفحة 16 — «الانثالبي دالة حالة وهي خاصية شاملة لانها تعتمد على كمية المادة»$q$, 8),
      (v_quiz, $q$الإشارة الموجبة للتغير في الانثالبي (ΔH) تعني أن العملية:$q$, $q$[{"key": "A", "text": "باعثة للحرارة"}, {"key": "B", "text": "غير قابلة للحدوث"}, {"key": "C", "text": "تلقائية دائماً"}, {"key": "D", "text": "ماصة للحرارة"}]$q$::jsonb, 'D', $q$ΔH موجبة تعني امتصاص حرارة من المحيط (مثل انصهار الجليد)، وΔH سالبة تعني انبعاث حرارة.

📖 المصدر: صفحة 19 — «فالاشارة الموجبة للانثالبي تعني ان التفاعل او العملية ماصة للحرارة»$q$, 9),
      (v_quiz, $q$صحيحة أم خاطئة؟ — عند عكس التفاعل الحراري تبقى إشارة انثالبي التفاعل كما هي.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$عند عكس العملية تتغير الإشارة: من الموجب إلى السالب إن كانت موجبة في الأصل، ومن السالب إلى الموجب إن كانت سالبة.

📖 المصدر: صفحة 21 — «فاشارة انثالبي التفاعل تتغير من الموجب للسالب اذا كانت اشارتها موجبة في الاصل»$q$, 10),
      (v_quiz, $q$تُعرَّف انثالبي التكوين القياسية بأنها الحرارة اللازمة (الممتصة أو المنبعثة) لتكوين:$q$, $q$[{"key": "A", "text": "مول واحد من أي مادة حرقاً تاماً مع الأوكسجين"}, {"key": "B", "text": "مول واحد من أي مركب من عناصره الأساسية بأثبت صورها"}, {"key": "C", "text": "غرام واحد من المركب من عناصره"}, {"key": "D", "text": "مولين من المركب من مركبات أبسط منه"}]$q$::jsonb, 'B', $q$انثالبي التكوين تخص تكوّن مول واحد من المركب من عناصره بأثبت صورها عند 25°C وضغط 1 atm، أما الحرق التام فهو انثالبي الاحتراق.

📖 المصدر: صفحة 22 — «لتكوين مول واحد من اي مركب من عناصره الاساسية»$q$, 11),
      (v_quiz, $q$صحيحة أم خاطئة؟ — الكاربون الماس (diamond) هو الصورة الأثبت لعنصر الكاربون في الظروف القياسية.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$الكرافيت هو الصورة الأثبت للكاربون، ولذلك تساوي انثالبي تكوينه القياسية صفراً.

📖 المصدر: صفحة 22 — «يعتبر الكرافيت هو الصورة»$q$, 12),
      (v_quiz, $q$ينص قانون هيس على أن التغير في انثالبي التفاعل:$q$, $q$[{"key": "A", "text": "يساوي دائماً صفراً للتفاعلات التلقائية"}, {"key": "B", "text": "يعتمد على المسار الذي يسلكه التفاعل"}, {"key": "C", "text": "يزداد كلما زاد عدد خطوات التفاعل"}, {"key": "D", "text": "هو نفسه سواء تم التفاعل في خطوة واحدة أو في سلسلة من الخطوات"}]$q$::jsonb, 'D', $q$قانون هيس يعتمد على أن الانثالبي دالة حالة، فيمكن حساب ΔH لتفاعل بجمع تفاعلات أخرى تؤدي إلى النتيجة نفسها.

📖 المصدر: صفحة 27 — «هو نفسه سواء تم التفاعل في خطوة واحدة او في سلسلة من الخطوات»$q$, 13),
      (v_quiz, $q$صحيحة أم خاطئة؟ — قيم انثالبي التبخر وانثالبي الانصهار موجبة دائماً لأنها حرارة ممتصة.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$التبخر والانصهار يمتصان حرارة فقيمهما موجبة، أما التكثيف والانجماد فيبعثان حرارة وقيمهما سالبة.

📖 المصدر: صفحة 27 — «تكون انثالبي التبخر والانصهار جميعها ذات قيم موجبة»$q$, 14),
      (v_quiz, $q$الانتروبي (S) هو مقياس:$q$, $q$[{"key": "A", "text": "لدرجة حرارة النظام"}, {"key": "B", "text": "لكمية الحرارة المنبعثة فقط"}, {"key": "C", "text": "لسرعة التفاعل"}, {"key": "D", "text": "للعشوائية أو لاانتظام النظام"}]$q$::jsonb, 'D', $q$كلما قلّ الانتظام في النظام (عشوائية أكبر) كانت قيمة الانتروبي كبيرة.

📖 المصدر: صفحة 34 — «مقياس للعشوائية او لاانتظام النظام»$q$, 15),
      (v_quiz, $q$أي الترتيبات الآتية صحيح لانتروبي حالات المادة؟$q$, $q$[{"key": "A", "text": "صلب > غاز > سائل"}, {"key": "B", "text": "سائل > غاز > صلب"}, {"key": "C", "text": "صلب > سائل > غاز"}, {"key": "D", "text": "غاز > سائل > صلب"}]$q$::jsonb, 'D', $q$انتروبي الحالة الغازية أكبر من السائلة، والسائلة أكبر من الصلبة، لأن العشوائية تزداد من الصلب إلى الغاز.

📖 المصدر: صفحة 34 — «انتروبي الحالة الغازية تكون دائما»$q$, 16),
      (v_quiz, $q$إذا كانت قيمة طاقة كبس الحرة للتفاعل سالبة (ΔG < 0) فإن التفاعل:$q$, $q$[{"key": "A", "text": "في حالة اتزان فقط"}, {"key": "B", "text": "يجري تلقائياً"}, {"key": "C", "text": "لا يحدث مطلقاً"}, {"key": "D", "text": "غير تلقائي"}]$q$::jsonb, 'B', $q$إشارة ΔG السالبة تدل على أن التفاعل أو التغير الفيزيائي يجري تلقائياً، والموجبة تدل على أنه غير تلقائي.

📖 المصدر: صفحة 39 — «يعني ان التفاعل او التغير الفيزيائي يجري تلقائياً»$q$, 17),
      (v_quiz, $q$أي العلاقات الآتية تمثل علاقة كبس عند ثبوت درجة الحرارة والضغط؟$q$, $q$[{"key": "A", "text": "ΔG = ΔS − TΔH"}, {"key": "B", "text": "ΔG = TΔH − ΔS"}, {"key": "C", "text": "ΔG = ΔH − TΔS"}, {"key": "D", "text": "ΔG = ΔH + TΔS"}]$q$::jsonb, 'C', $q$علاقة كبس: التغير في الطاقة الحرة يساوي التغير في الانثالبي مطروحاً منه حاصل ضرب درجة الحرارة في التغير في الانتروبي.

📖 المصدر: صفحة 39 — «ويعرف التغير في طاقة كبس الحرة»$q$, 18),
      (v_quiz, $q$صحيحة أم خاطئة؟ — إذا كانت ΔH و ΔS كلتاهما موجبتين فإن ΔG تصبح سالبة عندما تكون درجة الحرارة كبيرة.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$ΔG تكون سالبة عندما يصبح الحد TΔS أكبر بالمقدار من ΔH، ويتحقق ذلك عند درجات الحرارة العالية.

📖 المصدر: صفحة 41 — «عندما تكون T كبيرة»$q$, 19),
      (v_quiz, $q$صحيحة أم خاطئة؟ — عند درجتي حرارة الانصهار والغليان (حالة الاتزان) تساوي قيمة ΔG صفراً.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$عند هاتين الدرجتين يحدث اتزان بين الطورين فتكون ΔG مساوية للصفر.

📖 المصدر: صفحة 44 — «عند هذه الدرجات بالتحديد تساوي صفراً»$q$, 20),
      (v_quiz, $q$تساوي انثالبي التسامي:$q$, $q$[{"key": "A", "text": "انثالبي التبخر مقسوماً على درجة الغليان"}, {"key": "B", "text": "الفرق بين انثالبي التبخر والانصهار"}, {"key": "C", "text": "انثالبي الانصهار فقط"}, {"key": "D", "text": "مجموع انثالبيي الانصهار والتبخر"}]$q$::jsonb, 'D', $q$التسامي تحول المادة من الصلب إلى الغاز مباشرة، وانثالبيه تساوي مجموع انثالبيي الانصهار والتبخر لأن الانثالبي دالة حالة.

📖 المصدر: صفحة 45 — «انثالبي التسامي مجموع انثالبيات الانصهار والتبخر»$q$, 21);
  END IF;

  -- ===== الفصل الثاني: الاتزان الكيميائي =====
  SELECT id INTO v_chapter FROM public.chapters WHERE course_id = v_course AND (title = $q$الفصل الثاني: الاتزان الكيميائي$q$ OR sort_order = 2) ORDER BY created_at LIMIT 1;
  IF v_chapter IS NULL THEN
    INSERT INTO public.chapters (course_id, title, sort_order) VALUES (v_course, $q$الفصل الثاني: الاتزان الكيميائي$q$, 2) RETURNING id INTO v_chapter;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.quizzes WHERE chapter_id = v_chapter AND title = $q$اختبار تفاعلي — الفصل الثاني: الاتزان الكيميائي$q$) THEN
    INSERT INTO public.quizzes (chapter_id, title, description, pass_score, is_active)
    VALUES (v_chapter, $q$اختبار تفاعلي — الفصل الثاني: الاتزان الكيميائي$q$, $q$أسئلة مستخرجة من كتاب الكيمياء (PDF) مع تفسير علمي ومرجع الصفحة$q$, 50, false) RETURNING id INTO v_quiz;
    INSERT INTO public.questions (quiz_id, question_text, options, correct_answer, explanation, sort_order) VALUES
      (v_quiz, $q$التفاعلات غير الانعكاسية (التامة) هي التفاعلات التي:$q$, $q$[{"key": "A", "text": "لا تُستهلك فيها المواد المتفاعلة كلياً مهما طال الزمن"}, {"key": "B", "text": "تتساوى فيها سرعة التفاعل الأمامي مع سرعة التفاعل الخلفي"}, {"key": "C", "text": "يُستهلك فيها أحد المواد المتفاعلة أو جميعها استهلاكاً تاماً ولا تعود النواتج لتكوين المتفاعلات"}, {"key": "D", "text": "تُكتب دائماً بسهمين متعاكسين"}]$q$::jsonb, 'C', $q$في التفاعل غير الانعكاسي يُستهلك أحد المتفاعلات أو جميعها تماماً ويؤشر لذلك بسهم واحد، مثل احتراق البانزين.

📖 المصدر: صفحة 52 — «استهلاك تام لاحد أو جميع المواد المتفاعلة»$q$, 1),
      (v_quiz, $q$يُؤشَّر للتفاعل الانعكاسي في المعادلة الكيميائية بـ:$q$, $q$[{"key": "A", "text": "سهمين متعاكسين"}, {"key": "B", "text": "سهم واحد نحو اليسار"}, {"key": "C", "text": "علامة المساواة فقط"}, {"key": "D", "text": "سهم واحد نحو اليمين"}]$q$::jsonb, 'A', $q$وضع سهمين متعاكسين يدل على أن المواد الناتجة قادرة على التفاعل لتكوين المتفاعلات مرة أخرى.

📖 المصدر: صفحة 53 — «بوضع سهمين متعاكسين»$q$, 2),
      (v_quiz, $q$صحيحة أم خاطئة؟ — احتراق وقود السيارات (البانزين) احتراقاً تاماً مثال على تفاعل غير انعكاسي.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$من الصعب جداً إعادة ثنائي أوكسيد الكاربون وبخار الماء الناتجين إلى بانزين، لذلك فهو تفاعل تام باتجاه واحد.

📖 المصدر: صفحة 52 — «عند احتراق وقود السيارات (البانزين)»$q$, 3),
      (v_quiz, $q$عند وصول التفاعل الانعكاسي إلى حالة الاتزان الكيميائي:$q$, $q$[{"key": "A", "text": "تصبح سرعة التفاعل الخلفي صفراً"}, {"key": "B", "text": "تتساوى سرعة التفاعل الأمامي مع سرعة التفاعل الخلفي"}, {"key": "C", "text": "تنعدم تراكيز المواد المتفاعلة"}, {"key": "D", "text": "يتوقف التفاعل الأمامي تماماً"}]$q$::jsonb, 'B', $q$يستمر التفاعلان بالاتجاهين حتى تتساوى سرعتاهما (Rf = Rb) فيصل التفاعل إلى حالة الاتزان.

📖 المصدر: صفحة 54 — «حتى يصل التفاعل الى حالة معينة تتساوى»$q$, 4),
      (v_quiz, $q$يوصف الاتزان الكيميائي بأنه:$q$, $q$[{"key": "A", "text": "اتزان استاتيكي (ساكن)"}, {"key": "B", "text": "اتزان ديناميكي (حركي)"}, {"key": "C", "text": "اتزان يتوقف فيه التفاعل"}, {"key": "D", "text": "اتزان لا تتغير فيه سرعة التفاعلين مطلقاً أثناء الوصول إليه فقط"}]$q$::jsonb, 'B', $q$التفاعل مستمر في الاتجاهين بالسرعة نفسها، لذلك هو اتزان ديناميكي وليس ساكناً.

📖 المصدر: صفحة 54 — «حالة اتزان ديناميكي (حركي) وليست حالة اتزان استاتيكي»$q$, 5),
      (v_quiz, $q$صحيحة أم خاطئة؟ — عند حالة الاتزان يتوقف التفاعلان الأمامي والخلفي توقفاً تاماً.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$تبدو التفاعلات عند الاتزان وكأنها توقفت، لكنها في الحقيقة مستمرة في الاتجاهين وتراكيز المواد ثابتة.

📖 المصدر: صفحة 54 — «لكنها في الحقيقة لاتزال مستمرة وتجري في كلا الاتجاهين»$q$, 6),
      (v_quiz, $q$ينص قانون فعل الكتلة على أنه عند ثبوت درجة الحرارة تتناسب سرعة التفاعل الكيميائي طردياً مع التراكيز المولارية للمواد المتفاعلة، كل منها مرفوع إلى أس يساوي:$q$, $q$[{"key": "A", "text": "عدد الطور الفيزيائي للمادة"}, {"key": "B", "text": "حجم إناء التفاعل"}, {"key": "C", "text": "عدد المولات الموضوع أمام كل مادة في المعادلة الموزونة"}, {"key": "D", "text": "درجة حرارة التفاعل"}]$q$::jsonb, 'C', $q$الأس لكل تركيز هو معامل المادة (عدد مولاتها) في المعادلة الكيميائية الموزونة.

📖 المصدر: صفحة 55 — «مرفوع الى اس يمثل عدد المولات الموضوع امام كل مادة في المعادلة الكيميائية الموزونة»$q$, 7),
      (v_quiz, $q$يُعرَّف ثابت الاتزان Kc بأنه حاصل ضرب التراكيز المولارية للمواد الناتجة عند الاتزان:$q$, $q$[{"key": "A", "text": "مضروباً في حاصل ضرب تراكيز المواد المتفاعلة"}, {"key": "B", "text": "مطروحاً منه حاصل ضرب تراكيز المواد المتفاعلة"}, {"key": "C", "text": "مقسوماً على حاصل ضرب تراكيز المواد المتفاعلة، كل منها مرفوع لأس عدد مولاتها"}, {"key": "D", "text": "مقسوماً على مجموع تراكيز المواد المتفاعلة دون أسس"}]$q$::jsonb, 'C', $q$Kc = [G]^g [H]^h / ([A]^a [B]^b) للتفاعل aA + bB ⇌ gG + hH، وهو ثابت عند ثبوت درجة الحرارة.

📖 المصدر: صفحة 57 — «حاصل ضرب التراكيز المولارية للمواد الناتجة عند حالة الاتزان مقسوما»$q$, 8),
      (v_quiz, $q$عند كتابة علاقة ثابت الاتزان للتفاعلات غير المتجانسة تُحذف منها:$q$, $q$[{"key": "A", "text": "تراكيز المواد الصلبة والسائلة النقية"}, {"key": "B", "text": "تراكيز النواتج جميعها"}, {"key": "C", "text": "درجة الحرارة"}, {"key": "D", "text": "تراكيز المواد الغازية"}]$q$::jsonb, 'A', $q$لأن المواد الصلبة والسائلة النقية يبقى تركيزها ثابتاً مهما تغيرت كمياتها.

📖 المصدر: صفحة 59 — «المواد الصلبة والسائلة النقية يبقى تركيزها ثابتا»$q$, 9),
      (v_quiz, $q$ثابت الاتزان Kc للتفكك الحراري لكاربونات الكالسيوم CaCO3(s) ⇌ CaO(s) + CO2(g) يساوي:$q$, $q$[{"key": "A", "text": "1 / [CaO]"}, {"key": "B", "text": "[CaO][CO2] / [CaCO3]"}, {"key": "C", "text": "[CO2]"}, {"key": "D", "text": "[CaCO3] / [CO2]"}]$q$::jsonb, 'C', $q$تُحذف المواد الصلبة CaCO3 وCaO من علاقة ثابت الاتزان فيبقى تركيز الغاز CO2 فقط.

📖 المصدر: صفحة 59 — «ثابت الاتزان للتفكك الحراري لكاربونات الكالسيوم»$q$, 10),
      (v_quiz, $q$إذا كانت قيمة ثابت الاتزان كبيرة جداً فهذا يدل على أن:$q$, $q$[{"key": "A", "text": "تركيز المواد المتفاعلة كبير جداً والتفاعل يسير في الاتجاه الخلفي"}, {"key": "B", "text": "تركيز المواد الناتجة كبير جداً والتفاعل يسير تقريباً في الاتجاه الأمامي"}, {"key": "C", "text": "التفاعل لا يصل إلى حالة الاتزان"}, {"key": "D", "text": "تراكيز المتفاعلات والنواتج متساوية تماماً"}]$q$::jsonb, 'B', $q$K كبيرة (K ≫ 1) تعني أن الاتزان يميل نحو اليمين أي نحو تكوين النواتج.

📖 المصدر: صفحة 66 — «اذا كانت قيمة ثابت الاتزان كبيرة جدا»$q$, 11),
