  -- ===== الفصل الثالث: الاتزان الايوني =====
  SELECT id INTO v_chapter FROM public.chapters WHERE course_id = v_course AND (title = $q$الفصل الثالث: الاتزان الايوني$q$ OR sort_order = 3) ORDER BY created_at LIMIT 1;
  IF v_chapter IS NULL THEN
    INSERT INTO public.chapters (course_id, title, sort_order) VALUES (v_course, $q$الفصل الثالث: الاتزان الايوني$q$, 3) RETURNING id INTO v_chapter;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.quizzes WHERE chapter_id = v_chapter AND title = $q$اختبار تفاعلي — الفصل الثالث: الاتزان الايوني$q$) THEN
    INSERT INTO public.quizzes (chapter_id, title, description, pass_score, is_active)
    VALUES (v_chapter, $q$اختبار تفاعلي — الفصل الثالث: الاتزان الايوني$q$, $q$أسئلة مستخرجة من كتاب الكيمياء (PDF) مع تفسير علمي ومرجع الصفحة$q$, 50, false) RETURNING id INTO v_quiz;
    INSERT INTO public.questions (quiz_id, question_text, options, correct_answer, explanation, sort_order) VALUES
      (v_quiz, $q$المواد التي لا توصل محاليلها المائية التيار الكهربائي تسمى:$q$, $q$[{"key": "A", "text": "المواد غير الالكتروليتية"}, {"key": "B", "text": "الالكتروليتات القوية"}, {"key": "C", "text": "الالكتروليتات الضعيفة"}, {"key": "D", "text": "المنصهرات الأيونية"}]$q$::jsonb, 'A', $q$السكر (السكروز) مثال على مادة غير الكتروليتية: محلولها المائي لا يوصل الكهربائية ولا يضيء المصباح.

📖 المصدر: صفحة 88 — «وتدعى بالمواد غير الالكتروليتية»$q$, 1),
      (v_quiz, $q$صحيحة أم خاطئة؟ — تكون محصلة الشحنة الكهربائية لمحاليل الالكتروليتات مساوية للصفر.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$المحلول يحتوي أيونات موجبة وسالبة بكميات متكافئة فيكون متعادلاً كهربائياً.

📖 المصدر: صفحة 88 — «تكون محصلة الشحنة الكهربائية لمحاليل الالكتروليتات مساوية للصفر»$q$, 2),
      (v_quiz, $q$ينتج عن ذوبان الالكتروليتات القوية في الماء محاليل:$q$, $q$[{"key": "A", "text": "عالية التوصيل للكهربائية"}, {"key": "B", "text": "لا تحتوي على أيونات"}, {"key": "C", "text": "غير موصلة للكهربائية"}, {"key": "D", "text": "ضعيفة التوصيل للكهربائية"}]$q$::jsonb, 'A', $q$الالكتروليتات القوية تتفكك تفككاً تاماً تقريباً إلى أيونات فتكون محاليلها عالية التوصيل.

📖 المصدر: صفحة 89 — «ينتج عن ذوبان هذه الالكتروليتات في الماء محاليل عالية التوصيل للكهربائية»$q$, 3),
      (v_quiz, $q$ما تركيز ايون الهيدروكسيد في محلول هيدروكسيد الباريوم Ba(OH)₂ تركيزه 0.03 M؟$q$, $q$[{"key": "A", "text": "0.06 M"}, {"key": "B", "text": "0.03 M"}, {"key": "C", "text": "0.09 M"}, {"key": "D", "text": "0.015 M"}]$q$::jsonb, 'A', $q$كل وحدة صيغة من Ba(OH)₂ تعطي أيون OH⁻ مرتين، فيكون التركيز 2 × 0.03 = 0.06 M.

