      (v_quiz, $q$ينتج عن ذوبان الالكتروليتات الضعيفة في الماء محاليل ضعيفة التوصيل للكهربائية، لأنها:$q$, $q$[{"key": "A", "text": "لا تذوب في الماء مطلقاً"}, {"key": "B", "text": "تتفكك تماماً إلى أيونات"}, {"key": "C", "text": "تتأين بشكل جزئي في محاليلها المائية"}, {"key": "D", "text": "تحتوي على أيونات موجبة فقط"}]$q$::jsonb, 'C', $q$التأين الجزئي يعني أن عدد الأيونات قليل، فتضيء المصباح بشكل خافت.

📖 المصدر: صفحة 90 — «لكونها تتاين بشكل جزئي»$q$, 5),
      (v_quiz, $q$صحيحة أم خاطئة؟ — إذا كان الحامض قوياً فإن قاعدته القرينة تكون قوية أيضاً.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$الحامض القوي تكون قاعدته القرينة ضعيفة، والعكس صحيح.

📖 المصدر: صفحة 92 — «فاذا كان الحامض قوي فان قاعدته القرينة تكون ضعيفة والعكس صحيح»$q$, 6),
      (v_quiz, $q$كلما ازدادت قيمة ثابت تفكك الحامض Ka فإن:$q$, $q$[{"key": "A", "text": "لا تتغير قوة الحامض"}, {"key": "B", "text": "قلّ تفككه وقلّت حموضته"}, {"key": "C", "text": "قلّ تفككه وازدادت حموضته"}, {"key": "D", "text": "ازداد تفككه وازدادت حموضته"}]$q$::jsonb, 'D', $q$ثابت التفكك مقياس لقوة الحامض النسبية: القيمة الأكبر تعني تفككاً أكبر وحموضة أعلى.

📖 المصدر: صفحة 94 — «فكلما ازدادت قيمة ثابت تفكك الحامض»$q$, 7),
      (v_quiz, $q$يمكن استعمال طريقة التقريب (إهمال x من التركيز الابتدائي) عندما تكون النسبة المئوية للتأين:$q$, $q$[{"key": "A", "text": "أكبر من 20%"}, {"key": "B", "text": "تساوي 50%"}, {"key": "C", "text": "أكبر من 5%"}, {"key": "D", "text": "أقل من 5%"}]$q$::jsonb, 'D', $q$إذا كانت النسبة المئوية للتأين أقل من 5% يكون ما يتفكك صغيراً جداً مقارنة بالتركيز الابتدائي فيصح التقريب.

📖 المصدر: صفحة 95 — «فيمكن عند ذاك استعمال عملية التقريب»$q$, 8),
      (v_quiz, $q$عند تخفيف محلول حامض ضعيف فإن درجة التفكك (النسبة المئوية للتأين):$q$, $q$[{"key": "A", "text": "تقل"}, {"key": "B", "text": "تصبح صفراً"}, {"key": "C", "text": "لا تتغير"}, {"key": "D", "text": "تزداد"}]$q$::jsonb, 'D', $q$التخفيف يزيح موقع الاتزان نحو زيادة تفكك المذاب (التأين)، لذلك ترتفع درجة التفكك (من 0.079 إلى 0.229 في مثال HF).

📖 المصدر: صفحة 99 — «تؤدي عملية تخفيف المحلول الى ازاحة موقع الاتزان»$q$, 9),
      (v_quiz, $q$صحيحة أم خاطئة؟ — عملية التأين الذاتي للماء هي عملية برتنة ذاتية (انتقال بروتون) وهي المسؤولة عن الصفة الأمفوتيرية للماء.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$الماء يمكن أن يعطي بروتوناً ويستقبله، لذلك يسلك سلوك الحامض والقاعدة (أمفوتيري).

📖 المصدر: صفحة 101 — «وهي المسؤولة عن الصفة الامفوتيرية للماء»$q$, 10),
      (v_quiz, $q$الأملاح المشتقة من قاعدة قوية وحامض قوي (مثل NaCl) تعطي محاليل:$q$, $q$[{"key": "A", "text": "قاعدية"}, {"key": "B", "text": "غير متأينة"}, {"key": "C", "text": "حامضية"}, {"key": "D", "text": "متعادلة"}]$q$::jsonb, 'D', $q$لا يتفاعل أي من أيوناتها مع الماء بشكل ملحوظ، فلا يضطرب اتزان تأين الماء ويبقى المحلول متعادلاً.

📖 المصدر: صفحة 107 — «وهذا النوع من الاملاح يعطي محاليل متعادلة»$q$, 11),
      (v_quiz, $q$عند إذابة ملح مشتق من قاعدة قوية وحامض ضعيف (مثل خلات الصوديوم) يكون المحلول:$q$, $q$[{"key": "A", "text": "متعادلاً دائماً"}, {"key": "B", "text": "حامضياً"}, {"key": "C", "text": "غير موصل للكهربائية"}, {"key": "D", "text": "قاعدياً"}]$q$::jsonb, 'D', $q$أيون الخلات (القاعدة القرينة للحامض الضعيف) يتفاعل مع الماء (تحلل مائي) فيزداد OH⁻ ويصبح المحلول قاعدياً.

📖 المصدر: صفحة 108 — «يكون المحلول الناتج ذا صفة قاعدية دائما»$q$, 12),
      (v_quiz, $q$ما قيمة ثابت التحلل المائي Kh لأيون الخلات إذا كان Kw = 1.0×10⁻¹⁴ و Ka لحامض الخليك = 1.8×10⁻⁵؟$q$, $q$[{"key": "A", "text": "1.8×10⁻¹⁹"}, {"key": "B", "text": "1.8×10⁻⁹"}, {"key": "C", "text": "5.6×10⁻¹⁰"}, {"key": "D", "text": "5.6×10⁻⁵"}]$q$::jsonb, 'C', $q$Kh = Kw ÷ Ka = (1.0×10⁻¹⁴) ÷ (1.8×10⁻⁵) = 5.6×10⁻¹⁰.

📖 المصدر: صفحة 109 — «K h= K w K a)CH 3COOH( = 1.0 ×10 -14 1.8 × 10 -5 = 5.6 × 10 -10»$q$, 13),
      (v_quiz, $q$محلول كلوريد الأمونيوم (ملح قاعدة ضعيفة وحامض قوي) يكون محلوله:$q$, $q$[{"key": "A", "text": "متعادلاً"}, {"key": "B", "text": "قاعدياً"}, {"key": "C", "text": "حامضياً"}, {"key": "D", "text": "غير قابل للتأين"}]$q$::jsonb, 'C', $q$الأيون الموجب (الحامض القرين للقاعدة الضعيفة) يتحلل مائياً فيزداد تركيز H⁺ ويصبح المحلول حامضياً.

📖 المصدر: صفحة 111 — «وجعل هذا النوع من المحاليل حامضية»$q$, 14),
      (v_quiz, $q$إضافة مركب يعطي أيوناً موجوداً أصلاً في محلول الكتروليت ضعيف تؤدي إلى:$q$, $q$[{"key": "A", "text": "تحول المحلول إلى الكتروليت قوي"}, {"key": "B", "text": "زيادة تأين الالكتروليت الضعيف"}, {"key": "C", "text": "تقليل تأين الالكتروليت الضعيف"}, {"key": "D", "text": "عدم حدوث أي تغيير"}]$q$::jsonb, 'C', $q$هذه الظاهرة تسمى تأثير الايون المشترك وهي نتيجة لقانون فعل الكتلة ولقاعدة لو شاتليه.

📖 المصدر: صفحة 113 — «فان ذلك يؤدي الى تقليل تأين الالكتروليت الضعيف»$q$, 15),
      (v_quiz, $q$يحضَّر محلول البفر عادة بمزج:$q$, $q$[{"key": "A", "text": "ماء نقي مع ملح متعادل"}, {"key": "B", "text": "حامض ضعيف مع أحد أملاحه"}, {"key": "C", "text": "حامض قوي مع قاعدة قوية"}, {"key": "D", "text": "حامض قوي مع ملحه"}]$q$::jsonb, 'B', $q$مثال: حامض الخليك مع خلات الصوديوم؛ أو قاعدة ضعيفة مع أحد أملاحها.

📖 المصدر: صفحة 116 — «يحضر هذا النوع من المحاليل عادة بمزج حامض ضعيف مع احد الاملاح المشتقة من هذا الحامض الضعيف»$q$, 16),
      (v_quiz, $q$أي العلاقات الآتية تستعمل لحساب pH محلول البفر؟$q$, $q$[{"key": "A", "text": "pH = pKa + log([الملح]/[الحامض])"}, {"key": "B", "text": "pH = 14 + log[H⁺]"}, {"key": "C", "text": "pH = pKa × [الملح]/[الحامض]"}, {"key": "D", "text": "pH = pKa − log([الملح]/[الحامض])"}]$q$::jsonb, 'A', $q$هذه معادلة هندرسون: pH تساوي pKa مضافاً إليها لوغاريتم نسبة تركيز الملح إلى تركيز الحامض.

📖 المصدر: صفحة 121 — «تطبق المعادلة الخاصة بحساب قيمة pH محلول بفر»$q$, 17),
      (v_quiz, $q$تتناسب ذوبانية المركب الأيوني شحيح الذوبان طردياً مع:$q$, $q$[{"key": "A", "text": "قيمة pH الماء النقي"}, {"key": "B", "text": "قيمة ثابت حاصل الذوبان Ksp"}, {"key": "C", "text": "كتلة المذيب فقط"}, {"key": "D", "text": "درجة غليان المركب"}]$q$::jsonb, 'B', $q$Ksp قيمة ثابتة عند ثبوت درجة الحرارة وتستعمل للتعبير عن ذوبانية الأملاح شحيحة الذوبان.

📖 المصدر: صفحة 122 — «حيث تتناسب ذوبانية المركب طرديا مع قيمة ثابت حاصل الذوبان»$q$, 18);
  END IF;

  -- ===== الفصل الرابع: تفاعلات التأكسد والاختزال والكيمياء الكهربائية =====
  SELECT id INTO v_chapter FROM public.chapters WHERE course_id = v_course AND (title = $q$الفصل الرابع: تفاعلات التأكسد والاختزال والكيمياء الكهربائية$q$ OR sort_order = 4) ORDER BY created_at LIMIT 1;
  IF v_chapter IS NULL THEN
    INSERT INTO public.chapters (course_id, title, sort_order) VALUES (v_course, $q$الفصل الرابع: تفاعلات التأكسد والاختزال والكيمياء الكهربائية$q$, 4) RETURNING id INTO v_chapter;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.quizzes WHERE chapter_id = v_chapter AND title = $q$اختبار تفاعلي — الفصل الرابع: تفاعلات التأكسد والاختزال والكيمياء الكهربائية$q$) THEN
    INSERT INTO public.quizzes (chapter_id, title, description, pass_score, is_active)
    VALUES (v_chapter, $q$اختبار تفاعلي — الفصل الرابع: تفاعلات التأكسد والاختزال والكيمياء الكهربائية$q$, $q$أسئلة مستخرجة من كتاب الكيمياء (PDF) مع تفسير علمي ومرجع الصفحة$q$, 50, false) RETURNING id INTO v_quiz;
    INSERT INTO public.questions (quiz_id, question_text, options, correct_answer, explanation, sort_order) VALUES
      (v_quiz, $q$عدد التأكسد لأي عنصر حر غير متحد (مثل Na و O₂ و H₂) يساوي:$q$, $q$[{"key": "A", "text": "+1"}, {"key": "B", "text": "−1"}, {"key": "C", "text": "صفراً"}, {"key": "D", "text": "عدد الإلكترونات في مداره الأخير"}]$q$::jsonb, 'C', $q$من قواعد حساب أعداد التأكسد: العنصر الحر غير المتحد عدد تأكسده صفر.

📖 المصدر: صفحة 134 — «عدد التأكسد لأي عنصر غير متحد (عنصر حر) يساوي صفرا»$q$, 1),
      (v_quiz, $q$التأكسد هو تغير كيميائي يصحبه:$q$, $q$[{"key": "A", "text": "فقدان بروتونات فقط"}, {"key": "B", "text": "فقدان إلكترونات وزيادة في عدد التأكسد"}, {"key": "C", "text": "اكتساب نيوترونات"}, {"key": "D", "text": "اكتساب إلكترونات ونقصان في عدد التأكسد"}]$q$::jsonb, 'B', $q$الذرة التي تفقد الإلكترونات يقال إنها تأكسدت ويزداد عدد تأكسدها.

📖 المصدر: صفحة 136 — «فقدان في الالكترونات من ذرة او مجموعة من الذرات ويؤدي لزيادة في اعداد التأكسد»$q$, 2),
      (v_quiz, $q$في تفاعل 2Na + Cl₂ → 2NaCl، ما الذي حدث لذرة الكلور؟$q$, $q$[{"key": "A", "text": "اكتسبت إلكتروناً واختُزلت وقلّ عدد تأكسدها من 0 إلى −1"}, {"key": "B", "text": "تحولت إلى أيون موجب"}, {"key": "C", "text": "بقي عدد تأكسدها صفراً"}, {"key": "D", "text": "فقدت إلكتروناً وتأكسدت"}]$q$::jsonb, 'A', $q$كل ذرة كلور اكتسبت إلكتروناً واحداً فقل عدد تأكسدها من الصفر إلى −1، وهذا اختزال.

📖 المصدر: صفحة 137 — «فالصنف المشترك في التفاعل الذي يقل فيه عدد التاكسد هو الذي قد تم اختزاله»$q$, 3),
      (v_quiz, $q$صحيحة أم خاطئة؟ — يمكن أن تحدث عملية التأكسد دون حدوث عملية اختزال مرافقة لها.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$المادة التي تتأكسد تقابلها دائماً مادة تختزل، ويكون عدد الإلكترونات المفقودة مساوياً للمكتسبة.

📖 المصدر: صفحة 137 — «لا يمكن أن تحدث عملية التاكسد دون حدوث عملية اختزال مرافقة لها»$q$, 4),
      (v_quiz, $q$العامل المختزل هو المادة التي:$q$, $q$[{"key": "A", "text": "تُختزل وتكتسب الإلكترونات"}, {"key": "B", "text": "يقل عدد تأكسدها"}, {"key": "C", "text": "لا يتغير عدد تأكسدها"}, {"key": "D", "text": "تتأكسد وتفقد الإلكترونات"}]$q$::jsonb, 'D', $q$العامل المختزل يفقد الإلكترونات ويزداد عدد تأكسده، فهو المادة التي تتأكسد وتسبب اختزال مادة أخرى.

📖 المصدر: صفحة 139 — «لذلك يكون العامل المختزل هي المادة التي تتأكسد»$q$, 5),
      (v_quiz, $q$العامل المؤكسد هو المادة التي:$q$, $q$[{"key": "A", "text": "تم أكسدتها (تفقد إلكترونات)"}, {"key": "B", "text": "لا تشارك في التفاعل"}, {"key": "C", "text": "يزداد عدد تأكسدها"}, {"key": "D", "text": "تم اختزالها (تكتسب إلكترونات)"}]$q$::jsonb, 'D', $q$العامل المؤكسد يكتسب الإلكترونات ويقل عدد تأكسده، لذلك فهو المادة التي تُختزل وتسبب تأكسد مادة أخرى.

📖 المصدر: صفحة 139 — «لذلك يكون العامل المؤكسد هو المادة التي تم إختزالها»$q$, 6),
      (v_quiz, $q$في الخلية الكهروكيميائية، القطب الذي تجري عنده عملية التأكسد يسمى:$q$, $q$[{"key": "A", "text": "قطب الهيدروجين القياسي"}, {"key": "B", "text": "الجسر الملحي"}, {"key": "C", "text": "الانود"}, {"key": "D", "text": "الكاثود"}]$q$::jsonb, 'C', $q$الانود هو القطب الذي يحدث عنده التأكسد وهو مصدر الإلكترونات، أما الكاثود فيحدث عنده الاختزال.

📖 المصدر: صفحة 140 — «وهو القطب الذي تجري عنده عملية التأكسد»$q$, 7),
      (v_quiz, $q$الخلايا الكلفانية (الفولتائية) هي الخلايا التي:$q$, $q$[{"key": "A", "text": "تتحول فيها الطاقة الكيميائية إلى طاقة كهربائية بتفاعل يجري تلقائياً"}, {"key": "B", "text": "تحتوي على قطب واحد فقط"}, {"key": "C", "text": "تتحول فيها الطاقة الكهربائية إلى كيميائية بتفاعل غير تلقائي"}, {"key": "D", "text": "لا يحدث فيها أي تفاعل"}]$q$::jsonb, 'A', $q$البطاريات من أنواع الخلايا الكلفانية، أما الخلايا الالكتروليتية فتستعمل الطاقة الكهربائية لإنجاز تفاعل غير تلقائي.

📖 المصدر: صفحة 141 — «تتحول فيها الطاقة الكيميائية الى طاقة كهربائية من خلال تفاعل كيميائي يجري تلقائياً»$q$, 8),
      (v_quiz, $q$ما وظيفة الجسر الملحي في الخلية الكلفانية؟$q$, $q$[{"key": "A", "text": "زيادة تركيز أيونات النحاس"}, {"key": "B", "text": "نقل الإلكترونات عبر السلك الخارجي"}, {"key": "C", "text": "حفظ البطارية من التلف الميكانيكي"}, {"key": "D", "text": "إكمال الدائرة الكهربائية بحركة الأيونات بين المحلولين"}]$q$::jsonb, 'D', $q$الإلكترونات تنتقل في الدائرة الخارجية (السلك)، أما في الدائرة الداخلية (الجسر الملحي) فينتقل التيار بحركة الأيونات.

📖 المصدر: صفحة 143 — «فالتوصيل الكهربائي يتم عبر انتقال الالكترونات في الدائرة الخارجية»$q$, 9),
      (v_quiz, $q$ما الجهد القياسي المتفق عليه لقطب الهيدروجين القياسي (SHE)؟$q$, $q$[{"key": "A", "text": "−1.00 V"}, {"key": "B", "text": "+0.763 V"}, {"key": "C", "text": "+1.00 V"}, {"key": "D", "text": "صفر فولت"}]$q$::jsonb, 'D', $q$اتفق الاتحاد الدولي للكيمياء الصرفة والتطبيقية (IUPAC) على أن جهده يساوي صفر فولت، ليكون مرجعاً لقياس جهود الأقطاب الأخرى.

📖 المصدر: صفحة 146 — «جهد قطب الهيدروجين القياسي يساوي صفر فولت»$q$, 10),
      (v_quiz, $q$لماذا يستعمل البلاتين في قطب الهيدروجين القياسي؟$q$, $q$[{"key": "A", "text": "لأنه أكثر الفلزات نشاطاً"}, {"key": "B", "text": "لأنه مادة خاملة لا تتأكسد ولا تُختزل في ظروف القطب"}, {"key": "C", "text": "لأنه يُنتج غاز الهيدروجين"}, {"key": "D", "text": "لأنه يذوب في المحلول"}]$q$::jsonb, 'B', $q$البلاتين خامل ويوفر سطحاً تتفكك عليه جزيئات الهيدروجين ووسيلة لتوصيل التيار مع الدائرة الخارجية.

📖 المصدر: صفحة 146 — «لانه مادة خاملة لا تعاني تأكسدا ً واختزالا ً تحت الظروف التي يستخدم بها»$q$, 11),
      (v_quiz, $q$عند ربط قطب الخارصين مع قطب الهيدروجين القياسي كان جهد الخلية القياسي +0.763 V والخارصين هو الانود، فما جهد الاختزال القياسي للخارصين؟$q$, $q$[{"key": "A", "text": "صفر"}, {"key": "B", "text": "+1.526 V"}, {"key": "C", "text": "−0.763 V"}, {"key": "D", "text": "+0.763 V"}]$q$::jsonb, 'C', $q$جهد التأكسد القياسي للخارصين = +0.763 V، وجهد الاختزال يساويه بالمقدار ويعاكسه بالإشارة: −0.763 V.

📖 المصدر: صفحة 148 — «ولذلك يكون جهد الاختزال القياسي له»$q$, 12),
      (v_quiz, $q$في جدول جهود الاختزال القياسية، كلما اتجهنا إلى أسفل الجدول فإن جهود الاختزال:$q$, $q$[{"key": "A", "text": "تصبح كلها موجبة"}, {"key": "B", "text": "تقل وتزداد قوة العنصر كعامل مختزل"}, {"key": "C", "text": "تزداد وتزداد قوة العنصر كعامل مؤكسد"}, {"key": "D", "text": "تبقى ثابتة"}]$q$::jsonb, 'B', $q$قلة جهد الاختزال تعني سهولة التأكسد، أي زيادة القوة كعامل مختزل.

📖 المصدر: صفحة 148 — «تقل جهود الاختزال القياسية كلما اتجهنا الى اسفل الجدول»$q$, 13),
      (v_quiz, $q$عند حساب جهد الخلية القياسي يُختار قطب الانود للعنصر الذي يمتلك:$q$, $q$[{"key": "A", "text": "أقل جهد اختزال قياسي"}, {"key": "B", "text": "أعلى عدد تأكسد"}, {"key": "C", "text": "أكبر كتلة ذرية"}, {"key": "D", "text": "أعلى جهد اختزال قياسي"}]$q$::jsonb, 'A', $q$الانود يحدث عنده التأكسد، ويُختار له العنصر ذو أقل جهد اختزال، بينما يُختار للكاثود العنصر ذو أعلى جهد اختزال.

📖 المصدر: صفحة 149 — «يتم اختيار قطب الانود للعنصر الذي يمتلك اقل جهد اختزال قياسي»$q$, 14),
      (v_quiz, $q$تكافئ شحنة مول واحد من الإلكترونات (واحد فاراداي) تقريباً:$q$, $q$[{"key": "A", "text": "96500 كولوم"}, {"key": "B", "text": "1.6×10⁻¹⁹ كولوم"}, {"key": "C", "text": "9650 كولوم"}, {"key": "D", "text": "1 كولوم"}]$q$::jsonb, 'A', $q$ثابت فاراداي F = 96500 C/mol e⁻، وهو حاصل ضرب شحنة الإلكترون في عدد أفوكادرو.

📖 المصدر: صفحة 161 — «تكافئ 96500 C او واحد فاراداي»$q$, 15),
      (v_quiz, $q$ينص قانون فاراداي الأول على أن كتلة المادة المترسبة على الكاثود:$q$, $q$[{"key": "A", "text": "تتناسب عكسياً مع كمية الكهربائية"}, {"key": "B", "text": "لا تعتمد على الكهربائية"}, {"key": "C", "text": "تتناسب طردياً مع كمية الكهربائية المارة في الخلية"}, {"key": "D", "text": "تتناسب مع حجم الخلية فقط"}]$q$::jsonb, 'C', $q$كلما زادت كمية الكهربائية (الشحنة) المارة زادت كتلة المادة المترسبة أو المتحررة.

📖 المصدر: صفحة 160 — «تتناسب طرديا ً كتلة اي مادة تترسب على الكاثود»$q$, 16),
      (v_quiz, $q$ما كتلة المغنيسيوم (الكتلة الذرية 24) التي تترسب عند مرور تيار 25 A لمدة ساعة واحدة في محلول يحتوي Mg²⁺؟$q$, $q$[{"key": "A", "text": "22.4 g تقريباً"}, {"key": "B", "text": "5.6 g تقريباً"}, {"key": "C", "text": "11.2 g تقريباً"}, {"key": "D", "text": "0.9 g تقريباً"}]$q$::jsonb, 'C', $q$Q = 25 × 3600 ÷ 96500 ≈ 0.93 mol e⁻، ومن 2 mol e⁻ يترسب 1 mol Mg، فعدد المولات ≈ 0.466 وكتلة المغنيسيوم ≈ 0.466 × 24 ≈ 11.2 g.

📖 المصدر: صفحة 162 — «احسب عدد غرامات المغنيسيوم التي يمكن انتاجها»$q$, 17),
      (v_quiz, $q$الغاية الرئيسة من عملية الطلاء الكهربائي هي:$q$, $q$[{"key": "A", "text": "زيادة وزن المعدن فقط"}, {"key": "B", "text": "تحويل المعدن إلى غاز"}, {"key": "C", "text": "حماية المعادن من الصدأ أو التآكل"}, {"key": "D", "text": "تقليل توصيل المعدن للكهرباء"}]$q$::jsonb, 'C', $q$الطلاء بطبقة رقيقة من فلز آخر (كالفضة) يحمي المعدن ويحسن مظهره؛ ويكون السطح المراد طلاؤه هو الكاثود.

📖 المصدر: صفحة 160 — «حماية المعادن من الصدأ او التآكل»$q$, 18),
      (v_quiz, $q$البطاريات الأولية هي البطاريات التي:$q$, $q$[{"key": "A", "text": "لا تحتوي على أقطاب"}, {"key": "B", "text": "تعمل بالطاقة الشمسية"}, {"key": "C", "text": "يمكن إعادة شحنها"}, {"key": "D", "text": "لا يمكن إعادة شحنها"}]$q$::jsonb, 'D', $q$تصنف البطاريات إلى أولية لا يمكن إعادة شحنها، وثانوية (كبطارية الخزن الرصاصية) يمكن إعادة شحنها.

📖 المصدر: صفحة 163 — «بطاريات اولية وهي التي لا يمكن اعادة شحنها»$q$, 19);
  END IF;

  -- ===== الفصل الخامس: الكيمياء التناسقية =====
