    INSERT INTO public.questions (quiz_id, question_text, options, correct_answer, explanation, sort_order) VALUES
      (v_quiz, $q$أي الآتية من المركبات المعقدة المهمة في حياتنا؟$q$, $q$[{"key": "A", "text": "الهيموكلوبين وفيتامين B12 والكلوروفيل"}, {"key": "B", "text": "السكر والنشا"}, {"key": "C", "text": "كلوريد الصوديوم وكلوريد البوتاسيوم"}, {"key": "D", "text": "الماء وثاني أوكسيد الكربون"}]$q$::jsonb, 'A', $q$الهيموكلوبين وفيتامين B12 والكلوروفيل أمثلة على مركبات معقدة (تناسقية) ذات أهمية حيوية.

📖 المصدر: صفحة 170 — «ومن المركبات المعقدة المهمة في حياتنا هي الهيموكلوبين وفيتامين B12 والكلوروفيل»$q$, 1),
      (v_quiz, $q$صحيحة أم خاطئة؟ — من الخواص المشتركة للعناصر الانتقالية أن لها حالات تأكسد متعددة وأن العديد من مركباتها ملونة.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'A', $q$للعناصر الانتقالية أغلفة d أو f مملوءة جزئياً، مما يعطيها حالات تأكسد متعددة ومركبات ملونة وصفات بارامغناطيسية.

📖 المصدر: صفحة 170 — «العديد من مركباتها ملونة»$q$, 2),
      (v_quiz, $q$الملح المزدوج (مثل ملح مور) عند إذابته في الماء:$q$, $q$[{"key": "A", "text": "يتحول إلى مركب عضوي"}, {"key": "B", "text": "يعطي الأيونات المكونة له كافة ويحتفظ كل أيون بصفاته المستقلة"}, {"key": "C", "text": "لا يعطي أي أيون"}, {"key": "D", "text": "يعطي بعض أيوناته فقط"}]$q$::jsonb, 'B', $q$في الملح المزدوج يمكن الكشف عن جميع الأيونات في المحلول، أما المركب التناسقي فلا يعطي كافة أيوناته.

📖 المصدر: صفحة 171 — «يعطي عند إذابته في الماء الايونات المكونة له كافة»$q$, 3),
      (v_quiz, $q$المركب التناسقي هو مركب إضافة مستقر:$q$, $q$[{"key": "A", "text": "لا يذوب في الماء مطلقاً"}, {"key": "B", "text": "يعطي كافة أيوناته عند ذوبانه"}, {"key": "C", "text": "لا يعطي كافة الأيونات المكونة له عند ذوبانه في الماء"}, {"key": "D", "text": "يتكون من عنصر واحد فقط"}]$q$::jsonb, 'C', $q$مثال: [Cu(NH₃)₄]SO₄ لا يعطي أيون Cu²⁺ حراً، بل يعطي أيون SO₄²⁻ والأيون المعقد.

📖 المصدر: صفحة 172 — «وهو مركب اضافة مستقر ولكنه لا يعطي كافة الايونات المكونة له عند ذوبانه في الماء»$q$, 4),
      (v_quiz, $q$تحضير أي مركب عام 1798 عُدّ البداية الحقيقية للكيمياء التناسقية؟$q$, $q$[{"key": "A", "text": "كلوريد الصوديوم"}, {"key": "B", "text": "هيدروكسيد الألمنيوم"}, {"key": "C", "text": "كلوريد سداسي أمين الكوبلت (III)"}, {"key": "D", "text": "كبريتات النحاس"}]$q$::jsonb, 'C', $q$أثار هذا المركب اهتماماً كبيراً لأن CoCl₃ و NH₃ كلاهما مركب مستقر ومشبع التكافؤ ومع ذلك اتحدا.

📖 المصدر: صفحة 173 — «البداية الحقيقية للكيمياء التناسقية»$q$, 5),
      (v_quiz, $q$حسب نظرية فرنر، التكافؤ الثانوي للفلز يسمى:$q$, $q$[{"key": "A", "text": "العدد الذري الفعال"}, {"key": "B", "text": "ثابت التفكك"}, {"key": "C", "text": "عدد التأكسد"}, {"key": "D", "text": "العدد التناسقي"}]$q$::jsonb, 'D', $q$التكافؤ الأولي يشبع بأيونات سالبة (يعادل عدد التأكسد)، أما التكافؤ الثانوي فيمثل العدد التناسقي.

📖 المصدر: صفحة 175 — «بالعدد التناسقي»$q$, 6),
      (v_quiz, $q$ما العدد التناسقي للكوبلت (III) في المركب CoCl₃·6NH₃ حسب نظرية فرنر؟$q$, $q$[{"key": "A", "text": "2"}, {"key": "B", "text": "6"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}]$q$::jsonb, 'B', $q$التكافؤ الثانوي يشبع بجزيئات الأمونيا الست المتعادلة، فيكون العدد التناسقي 6.

📖 المصدر: صفحة 175 — «أما التكافؤ الثانوي أو عدد التناسق فيشبع من قبل جزيئات الامونيا المتعادلة الست»$q$, 7),
      (v_quiz, $q$الأصرة التناسقية تتكون نتيجة تفاعل:$q$, $q$[{"key": "A", "text": "حامض قوي مع قاعدة قوية"}, {"key": "B", "text": "أيونين متشابهي الشحنة"}, {"key": "C", "text": "قاعدة لويس (الليكند) مع حامض لويس (الايون المركزي)"}, {"key": "D", "text": "فلزين مع بعضهما"}]$q$::jsonb, 'C', $q$الليكند يهب مزدوجاً إلكترونياً غير مشترك إلى أوربيتال فارغ في الايون المركزي.

📖 المصدر: صفحة 178 — «تفاعل قاعدة لويس الذي يسمى الليكند مع حامض لويس والذي يسمى الايون أو الفلز المركزي»$q$, 8),
      (v_quiz, $q$الليكند الذي يهب مزدوجين من الإلكترونات يسمى:$q$, $q$[{"key": "A", "text": "أحادي المخلب"}, {"key": "B", "text": "ثنائي المخلب"}, {"key": "C", "text": "معقداً مركزياً"}, {"key": "D", "text": "متعدد المخلب"}]$q$::jsonb, 'B', $q$الليكند أحادي المخلب يهب مزدوجاً واحداً، وثنائي المخلب مزدوجين، ومتعدد المخلب أكثر من مزدوجين.

📖 المصدر: صفحة 179 — «وعندما يهب مزدوجين من الالكترونات يدعى ثنائي المخلب»$q$, 9),
      (v_quiz, $q$أكثر أعداد التناسق شيوعاً هي:$q$, $q$[{"key": "A", "text": "7 و 9 و 11"}, {"key": "B", "text": "1 و 3 و 5"}, {"key": "C", "text": "2 و 4 و 6"}, {"key": "D", "text": "10 و 12 و 14"}]$q$::jsonb, 'C', $q$أعداد التناسق الشائعة زوجية هي 2 و 4 و 6، أما الأعداد الفردية فنادرة.

📖 المصدر: صفحة 179 — «واكثر أعداد التناسق شيوعا ً هي 2 و 4 و6»$q$, 10),
      (v_quiz, $q$الليكند EDTA هو ليكند:$q$, $q$[{"key": "A", "text": "أحادي المخلب"}, {"key": "B", "text": "سداسي السن (ست ذرات مانحة)"}, {"key": "C", "text": "لا يرتبط بالفلزات"}, {"key": "D", "text": "ثنائي المخلب"}]$q$::jsonb, 'B', $q$EDTA ليكند متعدد المخلب يحتوي على ست ذرات قادرة على الارتباط التناسقي.

📖 المصدر: صفحة 181 — «وهو ليكند سداسي السن لاحتوائه على ست ذرات قادرة على الارتباط التناسقي»$q$, 11),
      (v_quiz, $q$تسمى الليكندات التي ترتبط في موقعين أو أكثر في آن واحد بنفس الايون الفلزي:$q$, $q$[{"key": "A", "text": "الليكندات الكليتية"}, {"key": "B", "text": "الليكندات الأحادية"}, {"key": "C", "text": "الأملاح المزدوجة"}, {"key": "D", "text": "الأيونات المضادة"}]$q$::jsonb, 'A', $q$الليكندات الكليتية (Chelating ligands) تكوّن حلقات مع الايون الفلزي.

📖 المصدر: صفحة 182 — «تسمى الليكندات التي ترتبط في موقعين أو أكثر في آن واحد مع نفس الايون الفلزي»$q$, 12),
      (v_quiz, $q$تنص قاعدة العدد الذري الفعال على أن المعقد يكون مستقراً إذا كان مجموع الإلكترونات على الفلز والممنوحة من الليكندات يساوي:$q$, $q$[{"key": "A", "text": "العدد الذري لأحد الغازات النبيلة"}, {"key": "B", "text": "الصفر"}, {"key": "C", "text": "عدد الليكندات فقط"}, {"key": "D", "text": "عدد التأكسد للفلز"}]$q$::jsonb, 'A', $q$المجموع الكلي للإلكترونات على الذرة المركزية والممنوحة من الليكندات يسمى العدد الذري الفعال.

📖 المصدر: صفحة 182 — «ويسمى المجموع الكلي للالكترونات على الذرة المركزية والممنوحة»$q$, 13),
      (v_quiz, $q$صحيحة أم خاطئة؟ — قاعدة العدد الذري الفعال تنطبق على جميع المعقدات من دون أي استثناء.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$هناك عدد من المعقدات المستقرة لا تنطبق عليها القاعدة، لذلك تعد أهميتها محدودة.

📖 المصدر: صفحة 183 — «إلا أن هناك عدد من المعقدات تكون مستقرة على الرغم من عدم انطباق قاعدة العدد الذري الفعال عليها»$q$, 14),
      (v_quiz, $q$في المعقد [Co(NH₃)₅Cl]Cl₂، ما المكونات داخل المجال التناسقي؟$q$, $q$[{"key": "A", "text": "Co³⁺ وخمس جزيئات أمونيا وأيون كلوريد واحد"}, {"key": "B", "text": "الأمونيا فقط"}, {"key": "C", "text": "Co³⁺ وثلاثة أيونات كلوريد"}, {"key": "D", "text": "أيونا الكلوريد الخارجيان فقط"}]$q$::jsonb, 'A', $q$المجال التناسقي (الداخلي) يكتب بين الأقواس المربعة، أما أيونا Cl⁻ خارج الأقواس فهما في المجال الأيوني ويمكن ترسيبهما.

📖 المصدر: صفحة 180 — «مكون من ايون الفلز المركزي»$q$, 15);
