      (v_quiz, $q$عند التعامل بالتركيز العياري في التسحيح تطبق عند نقطة نهاية التفاعل العلاقة:$q$, $q$[{"key": "A", "text": "N₁ + V₁ = N₂ + V₂"}, {"key": "B", "text": "N₁ ÷ V₁ = N₂ × V₂"}, {"key": "C", "text": "N₁ − V₁ = N₂ − V₂"}, {"key": "D", "text": "N₁ × V₁ = N₂ × V₂"}]$q$::jsonb, 'D', $q$بالتركيز العياري يتكافأ عدد المكافئات الغرامية للمادتين عند نقطة النهاية دون كتابة المعادلة الموزونة.

