    INSERT INTO public.chapters (course_id, title, sort_order) VALUES (v_course, $q$الفصل السابع: الهيدروكاربونات المعوضة$q$, 7) RETURNING id INTO v_chapter;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.quizzes WHERE chapter_id = v_chapter AND title = $q$اختبار تفاعلي — الفصل السابع: الهيدروكاربونات المعوضة$q$) THEN
    INSERT INTO public.quizzes (chapter_id, title, description, pass_score, is_active)
    VALUES (v_chapter, $q$اختبار تفاعلي — الفصل السابع: الهيدروكاربونات المعوضة$q$, $q$أسئلة مستخرجة من كتاب الكيمياء (PDF) مع تفسير علمي ومرجع الصفحة$q$, 50, false) RETURNING id INTO v_quiz;
    INSERT INTO public.questions (quiz_id, question_text, options, correct_answer, explanation, sort_order) VALUES
      (v_quiz, $q$الهيدروكاربونات هي مركبات عضوية تحتوي على:$q$, $q$[{"key": "A", "text": "الكاربون والأوكسجين فقط"}, {"key": "B", "text": "الهيدروجين والأوكسجين فقط"}, {"key": "C", "text": "الكاربون والنتروجين فقط"}, {"key": "D", "text": "عنصري الكاربون والهيدروجين فقط"}]$q$::jsonb, 'D', $q$الهيدروكاربونات أبسط المركبات العضوية، وتحتوي على الكاربون والهيدروجين فقط.

📖 المصدر: صفحة 232 — «اذ تحتوي على عنصري الكاربون والهيدروجين فقط»$q$, 1),
      (v_quiz, $q$المركبات التي تشترك في صيغة جزيئية واحدة وتختلف في الصيغة البنائية تسمى:$q$, $q$[{"key": "A", "text": "المجاميع الوظيفية"}, {"key": "B", "text": "الايزومرات"}, {"key": "C", "text": "الأيونات المعقدة"}, {"key": "D", "text": "الألكانات فقط"}]$q$::jsonb, 'B', $q$مثال: ن-بيوتان و2-مثيل بروبان (ايزو بيوتان) لهما الصيغة C₄H₁₀ وتختلفان في درجات الغليان والانصهار.

📖 المصدر: صفحة 232 — «تشترك في صيغة جزيئية واحدة وتعرف بالايزومرات»$q$, 2),
      (v_quiz, $q$المجموعة الوظيفية (الفعالة) هي:$q$, $q$[{"key": "A", "text": "المذيب المستعمل في التفاعل"}, {"key": "B", "text": "العنصر أو مجموعة العناصر التي تكسب المركب العضوي صفات خاصة"}, {"key": "C", "text": "الرابطة المفردة بين ذرتي كاربون"}, {"key": "D", "text": "ذرة الكاربون الأولى في السلسلة"}]$q$::jsonb, 'B', $q$وجود عناصر غير الكاربون والهيدروجين في المركب يكسبه صفات تميّزه عن المركبات التي تخلو منها.

📖 المصدر: صفحة 233 — «وقد اصطلح على العنصر او مجموعة العناصر التي تكسب المركب العضوي صفات خاصة بالمجاميع الوظيفية»$q$, 3),
      (v_quiz, $q$مجموعة الألكيل هي المجموعة الناتجة عن:$q$, $q$[{"key": "A", "text": "اتحاد ذرتي هالوجين"}, {"key": "B", "text": "حذف ذرة هيدروجين من الألكان"}, {"key": "C", "text": "حذف ذرة كاربون من الألكين"}, {"key": "D", "text": "إضافة ذرة أوكسجين إلى الألكان"}]$q$::jsonb, 'B', $q$مثلاً: حذف H من الميثان يعطي مجموعة المثيل CH₃–.

📖 المصدر: صفحة 234 — «مجاميع الالكيل وهي ما ينتج عند حذف ذرة هيدروجين من الالكان»$q$, 4),
      (v_quiz, $q$النيوكليوفيل هو كاشف:$q$, $q$[{"key": "A", "text": "باحث عن النواة وغني بالإلكترونات"}, {"key": "B", "text": "باحث عن الإلكترونات وفقير بها"}, {"key": "C", "text": "متعادل لا يتفاعل"}, {"key": "D", "text": "يمتلك أوربيتالاً فارغاً"}]$q$::jsonb, 'A', $q$النيوكليوفيل يمتلك مزدوجاً إلكترونياً غير متآصر أو أكثر، أما الالكتروفيل فيبحث عن الإلكترونات ويمتلك أوربيتالاً فارغاً.

📖 المصدر: صفحة 236 — «النيوكليوفيل هو كاشف باحث عن النواة لانه غني بالالكترونات»$q$, 5),
      (v_quiz, $q$الالكتروفيل هو كاشف:$q$, $q$[{"key": "A", "text": "لا يتفاعل مع الألكينات"}, {"key": "B", "text": "غني بالإلكترونات"}, {"key": "C", "text": "يعطي مزدوجاً إلكترونياً دائماً"}, {"key": "D", "text": "باحث عن الإلكترون (فقير بالإلكترونات)"}]$q$::jsonb, 'D', $q$الالكتروفيل يمتلك أوربيتالاً فارغاً مهيأً لاستقبال مزدوج إلكتروني.

📖 المصدر: صفحة 236 — «الالكتروفيل هو كاشف باحث عن الالكترون (فقير بالالكترونات)»$q$, 6),
      (v_quiz, $q$عند إضافة HBr إلى البروبين وفق قاعدة ماركوفينيكوف يكون الناتج الرئيسي:$q$, $q$[{"key": "A", "text": "برومو ميثان"}, {"key": "B", "text": "3-برومو بروبان"}, {"key": "C", "text": "2-برومو بروبان"}, {"key": "D", "text": "1-برومو بروبان"}]$q$::jsonb, 'C', $q$الهيدروجين يضاف إلى الكاربون الحامل لأكثر عدد من ذرات الهيدروجين ويرتبط البروم بالكاربون الثانوي، لأن أيون الكاربونيوم الثانوي أكثر استقراراً.

📖 المصدر: صفحة 237 — «والناتج الرئيسي هو 2 - برومو بروبان وليس 1 - برومو بروبان»$q$, 7),
      (v_quiz, $q$ترتيب استقرار أيونات الكاربونيوم هو:$q$, $q$[{"key": "A", "text": "أولي > ثانوي > ثالثي"}, {"key": "B", "text": "كلها متساوية"}, {"key": "C", "text": "ثانوي > ثالثي > أولي"}, {"key": "D", "text": "ثالثي > ثانوي > أولي"}]$q$::jsonb, 'D', $q$أيون الكاربونيوم الثالثي أكثر استقراراً من الثانوي، والثانوي أكثر استقراراً من الأولي.

📖 المصدر: صفحة 237 — «اكثر استقرارا ً من أيون الكاربونيوم الثانوي»$q$, 8),
      (v_quiz, $q$صحيحة أم خاطئة؟ — هاليدات الألكيل تذوب في الماء لأنها تكوّن أواصر هيدروجينية معه.$q$, $q$[{"key": "A", "text": "صحيحة"}, {"key": "B", "text": "خاطئة"}]$q$::jsonb, 'B', $q$لا تذوب في الماء لعدم قابليتها على تكوين أواصر هيدروجينية، لكنها تذوب في المذيبات العضوية.

📖 المصدر: صفحة 238 — «لا تذوب في الماء ولكنها تذوب في المذيبات العضوية»$q$, 9),
      (v_quiz, $q$يتفاعل هاليد الألكيل مع محلول هيدروكسيد البوتاسيوم الكحولي لإنتاج:$q$, $q$[{"key": "A", "text": "الألكين"}, {"key": "B", "text": "الكحول"}, {"key": "C", "text": "الحامض العضوي"}, {"key": "D", "text": "الألديهايد"}]$q$::jsonb, 'A', $q$هذه إحدى طرائق تحضير الألكينات (حذف HX من هاليد الألكيل).

📖 المصدر: صفحة 239 — «يتفاعل هاليد الالكيل مع محلول هيدروكسيد البوتاسيوم الكحولي لانتاج الالكين»$q$, 10),
      (v_quiz, $q$تفاعل هاليدات الألكيل مع فلز المغنيسيوم في وسط من الإيثر الجاف ينتج:$q$, $q$[{"key": "A", "text": "كيتوناً"}, {"key": "B", "text": "كاشف كرينيارد"}, {"key": "C", "text": "كحولاً أولياً"}, {"key": "D", "text": "ألديهايداً"}]$q$::jsonb, 'B', $q$مثال: CH₃I + Mg → CH₃MgI (يوديد مغنيسيوم المثيل).

